print('tokens_ok', bool(simple_note_token), bool(gmail_token), bool(phone_token))

# Get current date/time from phone
now_resp = apis.phone.get_current_date_and_time()
print('now_resp', now_resp)

date_str = now_resp.get('date')
time_str = now_resp.get('time')

# Parse phone current date/time (example: 'Sunday, May 21, 2023' + '04:07 PM')
formats = [
    '%A, %B %d, %Y %I:%M %p',
    '%A, %b %d, %Y %I:%M %p',
    '%A, %B %d, %Y %I:%M:%S %p',
    '%B %d, %Y %I:%M %p',
]

now_parsed = None
for fmt in formats:
    try:
        now_parsed = datetime.strptime(f"{date_str} {time_str}", fmt)
        break
    except Exception:
        continue
if now_parsed is None:
    # fallback try without timezone
    now_parsed = datetime.now()

print('now_dt', now_parsed)

# Fetch SimpleNote meeting schedule note
meeting_note_id = 3084
meeting_note_full = apis.simple_note.show_note(access_token=simple_note_token, note_id=meeting_note_id)
content = meeting_note_full.get('content','')

# Parse meetings
lines = content.splitlines()
meetings=[]
i=0
while i < len(lines):
    line = lines[i].rstrip('\n')
    if line.startswith('Meeting Name:'):
        meeting_name = line.split(':',1)[1].strip()
        current={'meeting_name': meeting_name, 'attendees': [], 'day': None, 'time': None}
        i += 1
        while i < len(lines):
            l = lines[i].strip()
            if l.startswith('Meeting Name:'):
                break
            if l == 'Attendees:':
                i += 1
                while i < len(lines):
                    l2 = lines[i].strip()
                    if l2.startswith('- '):
                        current['attendees'].append(l2[2:].strip())
                        i += 1
                        continue
                    if l2.startswith('Day:') or l2.startswith('Time:') or l2.startswith('Meeting Name:'):
                        break
                    if l2 == '':
                        i += 1
                        continue
                    # unexpected line
                    i += 1
                continue
            if l.startswith('Day:'):
                current['day'] = l.split(':',1)[1].strip().strip("'")
                i += 1
                continue
            if l.startswith('Time:'):
                t = l.split(':',1)[1].strip()
                t = t.strip().strip('"').strip("'")
                current['time'] = t
                i += 1
                continue
            i += 1
        meetings.append(current)
        continue
    i += 1

print('meetings_parsed', len(meetings))
for m in meetings:
    print(m)

weekday_map={'Monday':0,'Tuesday':1,'Wednesday':2,'Thursday':3,'Friday':4,'Saturday':5,'Sunday':6}

def next_occurrence_within(now_dt, target_weekday, meeting_time_str, search_days=14):
    hour, minute = map(int, meeting_time_str.split(':'))
    for offset in range(0, search_days+1):
        d = now_dt.date() + timedelta(days=offset)
        if d.weekday() != target_weekday:
            continue
        dt = datetime(d.year, d.month, d.day, hour, minute)
        if dt > now_dt:
            return dt
    # if none found, allow equality by taking earliest future even if not >
    for offset in range(0, search_days+1):
        d = now_dt.date() + timedelta(days=offset)
        if d.weekday() != target_weekday:
            continue
        dt = datetime(d.year, d.month, d.day, hour, minute)
        return dt
    return None

# Compute reminder scheduled_send_at
for m in meetings:
    td = weekday_map.get(m['day'])
    if td is None:
        raise ValueError('Unknown day: '+str(m['day']))
    meeting_dt = next_occurrence_within(now_parsed, td, m['time'], search_days=14)
    m['meeting_dt'] = meeting_dt
    m['reminder_dt'] = meeting_dt - timedelta(minutes=30)
    m['scheduled_send_at'] = m['reminder_dt'].strftime('%Y-%m-%d|%H:%M:%S')

print('meetings_with_schedule')
for m in meetings:
    print(m['meeting_name'], m['day'], m['time'], 'meeting_dt', m['meeting_dt'], 'reminder_dt', m['reminder_dt'], 'scheduled_send_at', m['scheduled_send_at'])

# Find attendee emails via phone contacts
my_email = 'jamie-solomon@gmail.com'

unique_attendees = sorted(set(a for m in meetings for a in m['attendees']))
print('unique_attendees', unique_attendees)

# helper to choose best matching contacts

def find_emails_for_name(name):
    # search contacts by query name
    page_index=0
    page_limit=20
    results=[]
    while True:
        resp = apis.phone.search_contacts(access_token=phone_token, query=name, page_index=page_index, page_limit=page_limit)
        # API might return list or dict with contacts
        if not resp:
            break
        contacts = resp['contacts'] if isinstance(resp, dict) and 'contacts' in resp else resp
        if not contacts:
            break
        results.extend(contacts)
        if len(contacts) < page_limit:
            break
        page_index += 1
    # Filter exact first-name matches
    name_norm = name.strip().lower()
    filtered=[]
    for c in results:
        fn = (c.get('first_name') or '').lower()
        ln = (c.get('last_name') or '').lower()
        full = (fn+' '+ln).strip()
        if fn == name_norm or ln == name_norm or full == name_norm:
            filtered.append(c)
    chosen = filtered if filtered else results
    emails = []
    for c in chosen:
        email = c.get('email')
        if email:
            emails.append(email)
    # de-dup while preserving order
    seen=set(); dedup=[]
    for e in emails:
        if e not in seen:
            seen.add(e); dedup.append(e)
    return dedup, len(results), len(chosen)

attendee_to_emails = {}
for a in unique_attendees:
    emails, total_count, chosen_count = find_emails_for_name(a)
    attendee_to_emails[a] = emails
    print('attendee', a, 'emails', emails, 'search_total', total_count, 'chosen', chosen_count)

# Build per meeting recipient list excluding me
for m in meetings:
    recips=[]
    for a in m['attendees']:
        for e in attendee_to_emails.get(a, []):
            if e != my_email:
                recips.append(e)
    # de-dup
    seen=set(); dedup=[]
    for e in recips:
        if e not in seen:
            seen.add(e); dedup.append(e)
    m['recipient_email_addresses'] = dedup

print('meeting_recipients')
for m in meetings:
    print(m['meeting_name'], m['recipient_email_addresses'])

